package com.richfield.smartpantry;
import android.content.*;import android.os.*;import android.view.*;import android.widget.*;import androidx.recyclerview.widget.*;
public class MainActivity extends BaseActivity {DatabaseHelper db;LinearLayout root,body;@Override public void onCreate(Bundle b){super.onCreate(b);db=new DatabaseHelper(this);showList();}@Override protected void onResume(){super.onResume();if(db!=null)showList();}void showList(){root=page("My Pantry");TextView sub=new TextView(this);sub.setText("Track what you already have. Tap an item to edit or delete it.");sub.setTextSize(16);root.addView(sub);Button add=button("+ Add ingredient");add.setOnClickListener(v->startActivity(new Intent(this,EditIngredientActivity.class)));root.addView(add);body=new LinearLayout(this);body.setOrientation(LinearLayout.VERTICAL);root.addView(body,new LinearLayout.LayoutParams(-1,0,1));RecyclerView list=new RecyclerView(this);list.setLayoutManager(new LinearLayoutManager(this));list.setAdapter(new PantryAdapter(db.ingredients(),i->{Intent x=new Intent(this,EditIngredientActivity.class);x.putExtra("id",i.id);startActivity(x);}));body.addView(list,new LinearLayout.LayoutParams(-1,-1));nav(root);setContentView(root);}}
